"""
Builds benchmarks/dungeon.bb with blitzcc, runs it and prints the frame times and what the frames cost: a walk through
a dungeon of rooms and corridors, lit by torches with flames and smoke. The result is also saved as JSON (and added to a CSV) in benchmarks/results/.

    python3 benchmarks/dungeon.py [--rooms N] [--torches N] [--particles N] [--props N] [--campfires N] [--sprite-scale N] [--depth-fade N]
                                  [--coverage] [--static] [common options, see --help]

--rooms defaults to $BENCH_ROOMS or 16, --torches (per room) to 4, --particles (flame and smoke sprites per torch) to 12,
--props (loose barrels, crates and balls per room) to 6, --frames to $BENCH_FRAMES or 600; "--rooms 100 --torches 6" is the heavy run, and
"--quick" is 4 rooms and 30 frames for a look whether it works. -d builds without optimization; the build configuration is part of the result so runs are not mixed up.

The original Blitz3D works too, so that its speed can be compared: --blitzcc C:\\Blitz3D\\bin\\blitzcc.exe (BLITZPATH is set to the
folder with bin\\ in it unless it is set). It has no -O3 and no --profile, and no draw counters (they are 0).

Without a display the program runs under xvfb-run, which with Mesa means llvmpipe: the times are then mostly the CPU
rasterizing and only a smoke test. The counts (draws, triangles) are exact on any GPU.
"""
import os
import benchutil


def main():
    runner = benchutil.Runner("dungeon", __doc__, frames=600)
    parser = runner.parser
    parser.add_argument("--rooms", type=int, default=int(os.environ.get("BENCH_ROOMS", 16)))
    parser.add_argument("--torches", type=int, default=int(os.environ.get("BENCH_TORCHES", 4)))
    parser.add_argument("--particles", type=int, default=int(os.environ.get("BENCH_PARTICLES", 12)))
    parser.add_argument("--props", type=int, default=int(os.environ.get("BENCH_PROPS", 6)))
    parser.add_argument("--campfires", type=int, default=int(os.environ.get("BENCH_CAMPFIRES", 25)), help="chance in percent that a room has a campfire")
    parser.add_argument("--sprite-scale", type=float, default=float(os.environ.get("BENCH_SPRITESCALE", 1)), help="draw the flames and smoke this many times bigger: more overdraw, for a GPU bound run")
    parser.add_argument("--depth-fade", type=float, default=float(os.environ.get("BENCH_DEPTHFADE", 0)), help="SpriteDepthFade distance of the flames and smoke (BlitzLLVM only, 0 for none): the cost of the soft edges")
    parser.add_argument("--coverage", action="store_true", help="also count the sprites in the view of the camera (slow, not timed)")
    parser.add_argument("--static", action="store_true", help="the fire stays where it starts, only the camera moves")
    args = runner.parse()
    if args.quick:
        args.rooms = 4
    # The original Blitz3D crashes with more than 16128 sprites (they share one vertex buffer of 4 vertices each that grows 256 sprites
    # at a time), and 2 of them are the flame and smoke templates. dungeon.bb checks again with the campfires counted.
    sprites = args.rooms * args.torches * args.particles
    runner.original_limit(sprites > 16126, "The original Blitz3D crashes with more than 16126 flame and smoke sprites, and this run has %d (rooms x torches x particles). Use fewer." % sprites)
    env = {"BENCH_ROOMS": args.rooms, "BENCH_TORCHES": args.torches, "BENCH_PARTICLES": args.particles, "BENCH_PROPS": args.props, "BENCH_CAMPFIRES": args.campfires,
           "BENCH_COVERAGE": 1 if args.coverage else 0, "BENCH_SPRITESCALE": args.sprite_scale, "BENCH_DEPTHFADE": args.depth_fade, "BENCH_STATIC": 1 if args.static else 0}
    v = runner.run(env, "%d rooms" % args.rooms)
    runner.report(["rooms       %12d (%d with a campfire, %d torches each, %d sprites per torch, %d props)%s" % (v["rooms"], v["campfires"], v["torches"], v["particles"], v["props"], " (static)" if args.static else ""),
                   "sprites     %12d%s%s" % (v["sprites"], (" at %gx size" % v["spritescale"]) if v["spritescale"] != 1 else "", (" (%.0f in the view of the camera per frame)" % v["inview"]) if args.coverage else "")],
                  update="lights and particles")
    runner.save(str(args.rooms), ("rooms", "campfires", "spritescale", "sprites", "inview", "torches", "particles", "props", "static"))


if __name__ == "__main__":
    main()
